PAGE = dict(
    slug='z_tick_labels',
    title='Pane::z_tick_labels',
    signature='Pane& Pane::z_tick_labels(bool enable = true) noexcept',
    intro='Shows or hides the tick labels of the z axis, the numbers or words written beside its ticks. They are visible by default. With `false` the labels are not drawn, whether they are the automatic numbers or explicit text set with [`z_ticks`](z_ticks.md) or [`z_categories`](z_categories.md); the axis label ([`z_label`](z_label.md)), the axis line and the grid are not affected, and the axis keeps its range and its ticks. `true` shows them again, exactly as before. The state is stored in `z_axis().tick_labels_visible`.\n\nIt is per axis, it never throws, and it is read when the figure is rendered.',
    parameters='**enable** (`bool`, default `true`)\n    `false` hides the tick labels, `true` shows them.',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='readback', text='Visible by default. `tick_labels_visible` is true for a new axis, `false` hides the labels, and `true` (the default argument) shows them again.',
             code='auto fig = studio("z_labels_readback");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\nstd::cout << "new axis: " << pane.z_axis().tick_labels_visible << "\\n";\npane.z_tick_labels(false);\nstd::cout << "after false: " << pane.z_axis().tick_labels_visible << "\\n";\npane.z_tick_labels();\nstd::cout << "after the default argument: " << pane.z_axis().tick_labels_visible << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='effect', text='The effect. With the labels hidden the axis has no tick text; the texts of the figure show the ticks of this axis present and then absent.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nauto build = [&](bool visible) {\n  auto fig = studio("z_labels_effect");\n  auto& pane = fig.pane3("p");\n  pane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\n  pane.x_tick_labels(false);\npane.y_tick_labels(false);\n  pane.z_tick_labels(visible);\n  return fig.to_svg();\n};\nstd::cout << "visible: " << texts(build(true)) << "\\n";\nstd::cout << "hidden:  " << texts(build(false)) << "\\n";\nauto fig = studio("z_labels_effect_out");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\npane.z_tick_labels(false);\nfig.save_svg("figure.svg");'),
        dict(id='restore', text='Showing them again restores the figure exactly: hiding and then showing gives the figure that never changed the setting.',
             code='auto build = [&](bool hide_then_show) {\n  auto fig = studio("z_labels_restore");\n  auto& pane = fig.pane3("p");\n  pane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\n  if (hide_then_show) pane.z_tick_labels(false).z_tick_labels(true);\n  return fig.to_svg();\n};\nstd::cout << "equal: " << (build(true) == build(false)) << "\\n";\nauto fig = studio("z_labels_restore_out");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\nfig.save_svg("figure.svg");'),
        dict(id='explicit', text='Explicit tick labels are hidden too. Labels set with `z_ticks` are tick labels like any other, so `z_tick_labels(false)` hides them while the label of the axis (`z_label`) stays.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nauto fig = studio("z_labels_explicit");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{1, 2, 3, 4});\npane.x_tick_labels(false);\npane.y_tick_labels(false);\npane.z_ticks(std::vector<double>{1, 2, 3}, {"low", "mid", "high"});\npane.z_label("Axis label");\nstd::cout << "shown: " << texts(fig.to_svg()) << "\\n";\npane.z_tick_labels(false);\nstd::cout << "hidden: " << texts(fig.to_svg()) << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- `noexcept`. To hide the whole axis including its line, use [`Pane::axes_visible`](axes_visible.md).',
    see=['[`Pane::z_label`](z_label.md): the axis label, which stays.', '[`Pane::z_ticks`](z_ticks.md): explicit tick labels.', '[`Pane::axes_visible`](axes_visible.md): hides all axes.', '[`Pane::x_tick_labels`](x_tick_labels.md): the same setting for the x axis.', '[`Pane::y_tick_labels`](y_tick_labels.md): the same setting for the y axis.'],
)
